import 'server-only';

import { buildPartyRoomUrl } from '@shared/realtime/realtime-host';
import { SEAT_PROOF_HEADER } from '@shared/domain/events/protocol';
import type { IRoomMembershipVerifier } from '@shared/application/ports/social';

import { serverRealtimeHost } from '@/config/deployment.config';

const TIMEOUT_MS = 3000;
/** Seat ids are generated by the game server; anything else in the answer is ignored. */
const SEAT_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

/**
 * Asks the game worker (the room's Durable Object) which seat a seat proof holds: the session token
 * the worker issued to that seat, or the persistent id of a seat that predates tokens. The proof
 * travels in a header, never in the URL. Fails closed: a timeout or error means "not attested", so
 * the player just looks like they are in the menus until the next heartbeat.
 */
export class PartyRoomMembershipVerifier implements IRoomMembershipVerifier {
  constructor(private readonly host: string = serverRealtimeHost()) {}

  async seatOf(roomCode: string, seatProof: string): Promise<string | null> {
    try {
      const response = await fetch(buildPartyRoomUrl(this.host, roomCode), {
        cache: 'no-store',
        headers: { [SEAT_PROOF_HEADER]: seatProof },
        signal: AbortSignal.timeout(TIMEOUT_MS),
      });
      if (!response.ok) return null;
      const { seat } = (await response.json()) as { seat?: unknown };
      return typeof seat === 'string' && SEAT_PATTERN.test(seat) ? seat : null;
    } catch (error) {
      console.warn('[presence] seat attestation failed', error instanceof Error ? error.message : error);
      return null;
    }
  }
}
